// src/modules/explorer/activateView.ts
var activateView = async (app, name) => {
  const { workspace } = app;
  let leaf = null;
  const leaves = workspace.getLeavesOfType(name);
  if (leaves.length > 0) {
    leaf = leaves[0];
  } else {
    leaf = workspace.getLeaf("tab");
    if (!leaf) {
      return;
    }
    await leaf.setViewState({ type: name, active: true });
  }
  workspace.revealLeaf(leaf);
};

