// src/modules/globalTables/FileConfig.ts
var FileConfig = class {
  constructor(path4, vault) {
    this.path = path4;
    this.vault = vault;
    this.data = [];
    this.isLoaded = false;
    this.fileHandler = null;
  }
  async load() {
    await this.handleMigration();
    this.fileHandler = this.vault.getFileByPath(this.path);
    if (!this.fileHandler) {
      return;
    }
    this.data = JSON.parse(await this.vault.cachedRead(this.fileHandler));
    this.isLoaded = true;
  }
  async handleMigration() {
    this.fileHandler = this.vault.getFileByPath(this.path);
    if (this.fileHandler) {
      return;
    }
    if (this.path.endsWith(".sqlsealconfig")) {
      const oldPath = this.path.replace(".sqlsealconfig", ".sqlseal");
      const oldFile = this.vault.getFileByPath(oldPath);
      if (oldFile) {
        try {
          await this.vault.rename(oldFile, this.path);
          console.log(`SQLSeal: Migrated config file from ${oldPath} to ${this.path}`);
        } catch (error3) {
          console.error(`SQLSeal: Failed to migrate config file from ${oldPath} to ${this.path}:`, error3);
        }
      }
    }
  }
  async insert(v3) {
    if (!this.isLoaded) {
      await this.load();
    }
    this.data.push(v3);
    await this.save();
  }
  get items() {
    return this.data;
  }
  async save() {
    const data6 = JSON.stringify(this.data);
    if (!this.fileHandler) {
      this.fileHandler = await this.vault.create(this.path, data6);
      return;
    }
    await this.vault.modify(this.fileHandler, data6);
  }
  async remove(v3) {
    this.data = this.data.filter((d3) => d3 !== v3);
    await this.save();
  }
};

